# CELL 12: WITHIN-ELEMENT OUTLIERS AND THE PER-STRUCTURE TABLE   (2.0.13)
# ===========================================================================
# Two jobs.
#
# 1. The within-element outlier pass: is this site's shortest bond unusual
#    FOR THIS ELEMENT in this run? Robust z on the median and MAD, so a few
#    broken structures cannot move the reference.
#
# 2. The per-structure table. Everything in the quality CSV is per SITE, so
#    every structure-level fact - the integrity verdict, the screen results,
#    the instability index, the packing minima - has had to be recovered with
#    drop_duplicates('filename') by every consumer: the triage, the summary,
#    the shift test and every ad-hoc analysis. That table now exists.
#
# WHERE THE LINE WITH HUGINN NOW FALLS
#
# Huginn 4.0 exists to make sense of what Eir kicks out, and a large part of
# what it does is REDUCTION: rolling per-site rows up to structures, which it
# has to do because Eir shipped only a per-site table. Its own documentation
# records the trap - taking groupby('filename').first() of a per-site screen
# column finds 20 of 48 failing perovskites and misses 28.
#
# With build_structure_table below, that reduction is Eir's job and is done
# once, with the invariant asserted rather than assumed. What should stay in
# Huginn is everything that is not reduction:
#
#   - pooling several Eir runs into one analysis and tracking what was
#     filtered out of each
#   - family-specific interpretation, which Huginn handles with modules
#   - publication figures and journal styling
#   - provenance analysis across decades and journals
#
# Eir should answer 'is this entry sound, and what is the evidence'. Huginn
# should answer 'what does this pool of entries tell us'. Until now Eir could
# not answer its own question without an interpreter, because the answer was
# spread across 225 per-site columns.
#
# RETIRED at v2.0.13: eir_2_0_1_geometry_for_huginn.csv. Every one of its 26
# columns was already in the quality CSV, its filename hard-coded a version
# three releases old, and nothing read it by name - it existed to make the
# native geometry available downstream after the pymatgen pass was dropped,
# which the quality CSV does. Worse, the three within-element columns were
# written ONLY to it: they were attached to dfq in memory and the quality CSV
# was never re-saved, so they were absent from the 225-column file everything
# else reads. The quality CSV is now re-saved with them.
# ===========================================================================
import os as _os
import numpy as _np
import pandas as _pd

# v2.0.37: THE WITHIN-ELEMENT OUTLIER TEST IS RETIRED.
#
# It took a robust z of each site's shortest bond against every site of the
# same ELEMENT in the run, ignoring valence and coordination, and fired on
# 1232 of 9685 sites. On ICSD 162002 it called the La site a -10.7 sigma
# outlier where the configuration-aware statistic puts it at -4.7; on sites
# whose element appears at several valences it is measuring the valence
# distribution rather than the site.
#
# bond_size_z (v2.0.36) asks the same question against Gagne's mean and sd for
# the site's own element, VALENCE and COORDINATION, and M10 acts on it with a
# fitted threshold. Keeping a wrongly grouped statistic in a published export
# invites a reader to quote it, so the three columns and their two roll-ups
# are gone rather than deprecated.
#
def _is_true(s):
    """True where the value is boolean True, however it reached us.

    v2.0.17. Two wrong ways to ask this question were already in the file.

    `.fillna(False).sum()` on an object column works but downcasts, which
    pandas warns about and will stop doing. `.fillna(False).astype(bool)`
    silences the warning and introduces a real fault: on a frame read back
    from CSV the values are the STRINGS 'True' and 'False', and
    bool('False') is True, so every site would count as flagged.

    Eir writes these frames to disk and reads them back - that is the whole
    post-processing chain - so the test has to survive the round trip. One
    definition, used everywhere the question is asked.
    """
    return s.astype(str).str.strip().str.lower().eq('true')


def build_structure_table(df):
    """
    One row per structure: identity, integrity verdict, screen results,
    instability indices, packing minima and the measured-distance summary.

    Per-site columns are reduced explicitly rather than by taking the first
    row, because 'first' is only correct for columns that are genuinely
    constant within a structure, and several are not.
    """
    g = df.groupby('filename', sort=False)

    # constant within a structure: take the first non-null
    _const = ['icsd_code', 'chemical_formula', 'space_group', 'year', 'journal',
              'authors', 'measurement_conditions', 'gii', 'wagii',
              # v2.0.46: how the file was read (CELL 3, the reading stage)
              'cif_read_from', 'cif_block', 'cif_written_by',
              'cif_refined_with', 'cif_database', 'cif_reading_notes',
              # v2.0.25: the VALUE as well as the name. Leaving it off this
              # explicit whitelist is how n_sites_below_floor and
              # u_parameter failed to reach the CSV; three times is enough.
              'gii_site_averaged', 'gii_recommended', 'gii_recommended_value',
              'gii_all_sites',
              'gii_percentile_in_run', 'anion_anion_min', 'cation_cation_min',
              'polyanion_edge_min',                    # v2.0.46
              'alternative_contacts_set_aside',        # v2.0.46
              'cation_cation_contact',                 # v2.0.46
              'has_antisite_disorder', 'n_antisite_species', 'n_anion_sites',
              # the anion side, which the cation/anion diagnosis and its figure
              # both need and which was omitted from the first version of this
              # table: the figure reported its columns absent rather than
              # failing, which is the right behaviour but hid the gap.
              'anion_bvs_mean', 'anion_bvs_mean_weighted',
              'anion_deviation_mean', 'anion_deviation_mean_weighted',
              'anion_deviation_max', 'anion_worst_label', 'anion_worst_bvs',
              'anion_worst_ligands', 'anion_balances',
              'shift_verdict', 'shift_evidence',
              'n_sites_shift_proposed', 'bvs_diagnosis', 'bvs_diagnosis_detail',
              'structure_pgrm_tier', 'structure_pgrm_code',
              'structure_pgrm_reason', 'structure_pgrm_evidence',
              'structure_core_geometry_plausible',
              'structure_bvs_geometry_plausible', 'anion_packing_plausible',
              'cation_packing_plausible', 'structure_cn_plausible',
              'u_parameter', 'u_deviation', 'pyrochlore_48f_x',
              'pyrochlore_fluorite_limit', 'origin_choice',
              # v2.0.30: the propagated uncertainty and the basis it belongs
              # to. On this list from the day it was created rather than
              # after someone notices it missing from a figure, which is what
              # the note above is about.
              'gii_sigma', 'gii_sigma_basis',
              # v2.0.31, on the list from the day they were created
              'gii_site_averaged_sigma', 'gii_recommended_sigma',
              'gii_recommended_sigma_basis', 'max_coord_sigma',
              # v2.0.32, beside gii_uncorrected and wagii_uncorrected
              'gii_site_averaged_uncorrected',
              # v2.0.33
              'gii_recommended_value_uncorrected',
              # v2.0.37
              'wagii_sigma', 'wagii_sigma_basis',
              # v2.0.41: THE FOUR BOND_STR INDICES, WHICH NEVER REACHED THIS
              # TABLE.
              #
              # They are per-structure quantities computed once and broadcast
              # to every site, they are in the per-site CSV, and they were
              # absent from the per-structure CSV because this whitelist is
              # explicit and nobody added them. That is the third time - the
              # note at the head of the list says so - and it is why the
              # comparison against FullProf had to be done by re-reading the
              # 845-row site table.
              #
              # Checked before adding: all seven are single-valued within
              # every one of the 539 rock salt structures, so .first() is the
              # right aggregation and no any-False roll-up is involved.
              'gii_bondstr_old', 'gii_bondstr_a', 'gii_bondstr_b',
              'gii_bondstr_c', 'gii_bondstr_convention',
              'gii_bondstr_mult_source', 'gii_bondstr_n_no_mult',
              # v2.0.41: beside max_coord_sigma, see CELL 7
              'max_coord_sigma_source']
    # Every column above is taken with .first(), which is only correct if it
    # is genuinely constant within a structure. That is ASSERTED, not assumed.
    #
    # Eir carries both granularities under names differing by one prefix:
    # core_geometry_plausible is PER SITE, structure_core_geometry_plausible
    # is per structure, and they sit adjacent in a 225-column CSV. Taking
    # .first() of the per-site column finds 20 of 48 failing perovskites and
    # misses 28, because the failing site is usually not row one. Huginn 4.0
    # documents the same trap from the other side.
    #
    # Anything that turns out to vary is rolled up with ANY-FALSE-CONDEMNS
    # instead, and named in _rolled_up so a reader can see it happened.
    cols, rolled = {}, []
    for c in _const:
        if c not in df.columns:
            continue
        # nunique() ignoring NaN, because a column that is populated on ONE
        # site by design - shift_evidence, proposed_shift - is not varying,
        # it is sparse. Counting NaN as a value made every such column look
        # inconsistent and sent it through the any-False rule, which is
        # meaningless on a string.
        _varies = int((g[c].nunique(dropna=True) > 1).sum())
        if _varies == 0:
            cols[c] = g[c].first()          # first NON-NULL, pandas default
            continue
        _isfalse = df[c].astype(str).str.lower().eq('false')
        _istrue = df[c].astype(str).str.lower().eq('true')
        if (_isfalse | _istrue).any():
            # a boolean screen that genuinely differs between sites
            rolled.append(c)
            cols[c] = ~_isfalse.groupby(df['filename']).any()
        else:
            # not boolean, so any-False says nothing. Take the first non-null
            # and record that the column was not single-valued.
            rolled.append(c + ' (first non-null)')
            cols[c] = g[c].first()
    out = _pd.DataFrame(cols)
    if rolled:
        _shown = ', '.join(rolled[:5]) + (' ...' if len(rolled) > 5 else '')
        print(f'  [{len(rolled)} column(s) varied within a structure and were '
              f'rolled up any-False rather than taken from the first row: '
              f'{_shown}]')
    out.attrs['rolled_up'] = rolled

    # aggregated across the sites
    out['n_sites'] = g.size()
    for src, name, how in [
            ('bl_delta_mean', 'bl_delta_mean_median', 'median'),
            ('bl_ratio_min', 'bl_ratio_min_min', 'min'),
            ('min_bond_length', 'shortest_cation_anion', 'min'),
            ('econ_cn_ratio', 'econ_cn_ratio_min', 'min')]:
        if src in df.columns:
            out[name] = getattr(_pd.to_numeric(df[src], errors='coerce')
                                .groupby(df['filename']), how)()
    # v2.0.17: THESE TWO COLUMNS ASK DIFFERENT QUESTIONS AND WERE GIVEN
    # THE SAME TEST.
    #
    # cn_fault is a string in which null means no fault, so notna() is right
    # for it. within_element_flag is a boolean in which null means the site
    # could not be tested - too few of that element in the run to form a
    # median - so notna() counts the TESTED sites, not the FLAGGED ones.
    #
    # Measured on the 2.0.16 runs: perovskites 270 flagged against 1695
    # tested, pyrochlores 204 against 941, and the per-structure table
    # reported the tested figure in both. CELL 12's own printed line uses the
    # right test, so the summary said 204 and the CSV said 941 for the same
    # quantity. 270 is the figure the perovskite work has been quoting.
    #
    # The denominator is worth keeping rather than discarding: 192 of 1133
    # pyrochlore sites could not be tested at all, and a flag count means
    # little without knowing how many sites were eligible for it.
    if 'cn_fault' in df.columns:
        out['n_cn_faults'] = df['cn_fault'].notna().groupby(df['filename']).sum()
    # v2.0.37: THE IMPRECISION CENSUS, WHICH THE TIER CANNOT BE.
    #
    # M9 is asked last, so a structure that is both shared-site and imprecise
    # reports the sharing - deliberately, because sharing is the caveat a
    # reader cannot reconstruct from the export while the sigma is on every
    # row. The cost is that ACCEPT_IMPRECISE is not a census: 184 structures
    # recommended on the site-averaged index carry a sigma above the threshold
    # and none of them can reach the tier, because sharing is what made that
    # index the recommended one in the first place.
    #
    # So the census is a column. Same threshold, same source, no ordering
    # change, and the tier keeps meaning 'this is the caveat that applies'.
    if 'gii_recommended_sigma' in df.columns:
        _sg = _pd.to_numeric(df['gii_recommended_sigma'], errors='coerce')
        out['index_imprecise'] = (_sg > PGRM_IMPRECISE_SIGMA).groupby(
            df['filename']).any()
    if 'bl_tier' in df.columns:
        _t = _pd.to_numeric(df['bl_tier'], errors='coerce')
        out['n_bl_measured'] = (_t <= 2).groupby(df['filename']).sum()

    # how many independent screens failed. Computed here because every
    # consumer was rebuilding it, and they did not all use the same five.
    _screens = ['structure_core_geometry_plausible',
               'structure_bvs_geometry_plausible', 'anion_packing_plausible',
               'cation_packing_plausible', 'structure_cn_plausible']
    _have = [c for c in _screens if c in out.columns]
    if _have:
        _fail = sum(out[c].astype(str).str.lower().eq('false').astype(int)
                    for c in _have)
        if 'n_sites_shift_proposed' in out.columns:
            _fail = _fail + (_pd.to_numeric(out['n_sites_shift_proposed'],
                                            errors='coerce').fillna(0) > 0).astype(int)
        out['n_screens_failed'] = _fail
    return out.reset_index()
